<?php /** @var array $plans @var string $basePath */ ?><section class="l-page-hero"><p class="l-eyebrow">Maintenance plans</p><h1>Consistent care, simpler scheduling.</h1><p>Each plan is a starting point. Property size, conditions, route, and requested work determine the final estimate.</p></section><section class="l-section l-plan-grid"><?php foreach ($plans as $plan): ?><article class="l-plan<?= $plan['featured']?' is-featured':'' ?>"><p class="l-eyebrow"><?= e($plan['cadence']) ?></p><h2><?= e($plan['name']) ?></h2><p><?= e($plan['description']) ?></p><p class="l-price"><?= $plan['price_cents'] ? 'From $'.e(number_format($plan['price_cents']/100,2)) : e($plan['price_note']) ?></p><ul><?php foreach (preg_split('/\r?\n/',(string)$plan['inclusions']) as $line): if (trim($line)!==''): ?><li><?= e(trim($line)) ?></li><?php endif; endforeach; ?></ul><?php if($plan['seasonal_notes']): ?><p><small><?= e($plan['seasonal_notes']) ?></small></p><?php endif; ?><a class="l-btn l-btn-primary" href="<?= e_attr($basePath) ?>/request-estimate&amp;plan=<?= e_attr($plan['slug']) ?>">Request this plan</a></article><?php endforeach; ?></section>
